package app.layan.test;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.os.*;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import android.widget.*;
import app.layan.quran.*;
import app.layan.quran.prayer.*;
import org.threeten.bp.*;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;

/** Actual installed APK: event boundaries, DST, live header and both visual modes. */
public final class StylePrayerRegression extends Instrumentation {
 private Bundle args;private int checks;private final StringBuilder report=new StringBuilder();
 public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 private void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 private void log(String s){report.append(s).append('\n');}
 private void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
 private Object field(Activity a,String name)throws Exception{Field f=a.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(a);}
 private void call(Activity a,String name)throws Exception{Method m=a.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(a);}
 private String text(View v){StringBuilder b=new StringBuilder();if(v instanceof TextView)b.append(((TextView)v).getText()).append('\n');if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)b.append(text(((ViewGroup)v).getChildAt(i)));return b.toString();}
 private void seed(){getTargetContext().getSharedPreferences("layan_local",0).edit().putLong("prayer_lat",Double.doubleToLongBits(30.0444)).putLong("prayer_lon",Double.doubleToLongBits(31.2357)).putLong("prayer_location_time",System.currentTimeMillis()).putFloat("prayer_accuracy",100).commit();getTargetContext().getSharedPreferences("layan_qibla",0).edit().putBoolean("calib_intro_shown",true).putBoolean("location_asked",true).commit();}
 private Activity launch(String name){return startActivitySync(new Intent().setClassName(getTargetContext(),"app.layan.quran."+name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 private void awaitPrayer(Activity a)throws Exception{for(int i=0;i<300;i++){waitForIdleSync();if(field(a,"next")!=null&&field(a,"counter")!=null&&!((TextView)field(a,"counter")).getText().toString().isEmpty())return;SystemClock.sleep(200);}throw new AssertionError("Prayer calculation timed out: "+text(a.getWindow().getDecorView()));}
 private void shot(Activity a,String name)throws Exception{SystemClock.sleep(900);AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null)for(AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText("Wait"))if("android".contentEquals(node.getPackageName()))node.performAction(AccessibilityNodeInfo.ACTION_CLICK);SystemClock.sleep(500);root=getUiAutomation().getRootInActiveWindow();check(root!=null,"Active screen "+name);check("app.layan.quran".contentEquals(root.getPackageName()),"Layan must be visible for "+name);for(String error:new String[]{"isn't responding","keeps stopping"})check(root.findAccessibilityNodeInfosByText(error).isEmpty(),"Error covers "+name);Bitmap b=getUiAutomation().takeScreenshot();check(b!=null,"Screenshot "+name);File f=new File(a.getExternalFilesDir("tests"),"style-"+name+".png");f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 private void calculations(){ZoneId cairo=ZoneId.of("Africa/Cairo");ReferencePrayer engine=new ReferencePrayer(30.0444,31.2357,-9999,cairo,"ega",Collections.emptyMap());ReferencePrayer utc=new ReferencePrayer(30.0444,31.2357,-9999,ZoneId.of("UTC"),"ega",Collections.emptyMap());for(String ds:new String[]{"2026-01-15","2026-04-23","2026-04-24","2026-07-15","2026-10-29","2026-10-30"}){LocalDate date=LocalDate.parse(ds);List<ReferencePrayer.Event> schedule=new ArrayList<>();for(int d=-1;d<=2;d++)for(ReferencePrayer.Event e:engine.times(date.plusDays(d)))if(Arrays.asList(ReferencePrayer.REQUIRED).contains(e.id))schedule.add(e);schedule.sort(Comparator.comparing(e->e.instant));List<ReferencePrayer.Event> utcTimes=utc.times(date);for(ReferencePrayer.Event event:engine.times(date)){if(!Arrays.asList(ReferencePrayer.REQUIRED).contains(event.id))continue;ReferencePrayer.Event universal=null;for(ReferencePrayer.Event e:utcTimes)if(e.id.equals(event.id))universal=e;check(universal!=null&&universal.instant.equals(event.instant),"UTC/Cairo instant differs: "+ds+" "+event.id);for(int offset:new int[]{-1,0,1}){Instant now=event.instant.plusMillis(offset);ReferencePrayer.Event expected=null;for(ReferencePrayer.Event e:schedule)if(e.instant.isAfter(now)){expected=e;break;}ReferencePrayer.Event actual=engine.next(now);check(expected!=null&&actual.id.equals(expected.id)&&actual.instant.equals(expected.instant),"Boundary selection "+ds+" "+event.id+" "+offset);check(ReferencePrayer.secondsLeft(now.toEpochMilli(),actual.instant.toEpochMilli())==(actual.instant.toEpochMilli()-now.toEpochMilli()+999)/1000,"Countdown rounding");}}
  ReferencePrayer.Event after=engine.next(date.atTime(23,55).atZone(cairo).toInstant());check(after.id.equals("fajr")&&after.instant.atZone(cairo).toLocalDate().equals(date.plusDays(1)),"Next-day Fajr "+ds);log(ds+": all five prayers, before/exact/after boundary and UTC equality passed.");}
 check(cairo.getRules().getOffset(Instant.parse("2026-01-15T12:00:00Z")).getTotalSeconds()==7200,"Winter offset");check(cairo.getRules().getOffset(Instant.parse("2026-07-15T12:00:00Z")).getTotalSeconds()==10800,"Summer offset");}
 private void livePrayer()throws Exception{seed();Activity a=launch("PrayerActivity");awaitPrayer(a);for(int day:new int[]{0,1,-1,0}){ui(()->{try{Field offset=a.getClass().getDeclaredField("dayOffset");offset.setAccessible(true);offset.setInt(a,day);Field next=a.getClass().getDeclaredField("next");next.setAccessible(true);next.set(a,null);call(a,"compute");}catch(Exception e){throw new RuntimeException(e);}});awaitPrayer(a);ReferencePrayer.Event next=(ReferencePrayer.Event)field(a,"next");ZoneId zone=(ZoneId)field(a,"zone");Method eventName=a.getClass().getDeclaredMethod("eventName",String.class,LocalDate.class);eventName.setAccessible(true);String name=(String)eventName.invoke(a,next.id,next.instant.atZone(zone).toLocalDate());String screen=text(a.getWindow().getDecorView());check(screen.contains(" · "+name),"Header must identify actual upcoming event, day offset "+day);check(((TextView)field(a,"counter")).getText().toString().startsWith(name+"  − "),"Counter and header must name the same prayer");check(next.instant.isAfter(Instant.now()),"Upcoming event must be in future");if(day==1)shot(a,"prayer-tomorrow-live-countdown");}shot(a,"prayer-day");ui(()->{try{call(a,"calculationSettings");}catch(Exception e){throw new RuntimeException(e);}});shot(a,"prayer-settings-day");ui(a::finish);log("Live header/countdown agree while browsing yesterday/today/tomorrow.");}
 private View toolbar(View v){if(v.getClass().getName().endsWith("Toolbar"))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=toolbar(((ViewGroup)v).getChildAt(i));if(found!=null)return found;}return null;}
 private View described(View v,String description){if(description.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=described(((ViewGroup)v).getChildAt(i),description);if(found!=null)return found;}return null;}
 private void themeToggle()throws Exception{SharedPreferences prefs=android.preference.PreferenceManager.getDefaultSharedPreferences(getTargetContext());prefs.edit().putBoolean("nightMode",false).commit();Activity a=launch("QuranPreferenceActivity");ActivityMonitor monitor=addMonitor("app.layan.quran.QuranPreferenceActivity",null,false);ui(()->{prefs.edit().putBoolean("nightMode",true).commit();LayanUi.apply(a);});Activity night=waitForMonitorWithTimeout(monitor,30000);removeMonitor(monitor);check(night!=null,"Existing settings must recreate after night toggle");waitForIdleSync();android.util.TypedValue color=new android.util.TypedValue();check(night.getTheme().resolveAttribute(android.R.attr.colorBackgroundFloating,color,true)&&color.data==0xff192b22,"Night cards must match the new theme");check(night.getWindow().getStatusBarColor()==0xff0e1915,"Live night status bar");shot(night,"settings-live-night-toggle");ui(night::finish);prefs.edit().putBoolean("nightMode",false).commit();log("Changing night mode refreshes the existing settings screen and card resources.");}
 private void menus()throws Exception{SharedPreferences prefs=android.preference.PreferenceManager.getDefaultSharedPreferences(getTargetContext());for(boolean dark:new boolean[]{false,true}){prefs.edit().putBoolean("nightMode",dark).commit();Activity home=launch("ui.QuranActivity");check(home.findViewById(0x7f090268)!=null,"Main index preserved");ui(home::openOptionsMenu);shot(home,"home-menu-"+(dark?"night":"day"));AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();check(root!=null&&!root.findAccessibilityNodeInfosByText("الصلاة").isEmpty(),"Actual overflow menu opens");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);shot(home,"ui-QuranActivity-"+(dark?"night":"day"));ui(home::finish);for(String name:new String[]{"SearchActivity","ui.TranslationManagerActivity","HelpActivity"}){Activity a=launch(name);shot(a,name.replace('.','-')+"-"+(dark?"night":"day"));ui(a::finish);}log("Menu icons, actual overflow and original search/translations/help opened "+(dark?"night":"day"));}prefs.edit().putBoolean("nightMode",false).commit();}
 private void styles()throws Exception{seed();SharedPreferences prefs=android.preference.PreferenceManager.getDefaultSharedPreferences(getTargetContext());for(boolean dark:new boolean[]{false,true}){prefs.edit().putBoolean("nightMode",dark).commit();for(String name:new String[]{"ui.QuranActivity","QuranPreferenceActivity","QuranAdvancedPreferenceActivity","QiraatActivity","HadithActivity","AzkarActivity","LayanInfoActivity","QiblaActivity","PrayerActivity"}){Activity a=launch(name);if(name.equals("QiblaActivity"))runOnMainSync(()->{try{((android.hardware.SensorManager)field(a,"sensors")).unregisterListener((android.hardware.SensorEventListener)a);}catch(Exception e){throw new RuntimeException(e);}});if(name.equals("PrayerActivity"))awaitPrayer(a);waitForIdleSync();LayanUi.Palette p=new LayanUi.Palette(a);check(p.dark==dark,"Mode "+name);check(a.getWindow().getStatusBarColor()==p.background,"Status bar palette "+name);check(a.findViewById(android.R.id.content).getBackground() instanceof ColorDrawable&&((ColorDrawable)a.findViewById(android.R.id.content).getBackground()).getColor()==p.background,"Content palette "+name);if(name.equals("ui.QuranActivity")){check(a.findViewById(0x7f090268)!=null,"Main index row preserved");View bar=toolbar(a.getWindow().getDecorView());check(bar!=null,"Main toolbar");ui(a::openOptionsMenu);shot(a,"home-menu-"+(dark?"night":"day"));sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);}
 if(name.equals("QiraatActivity"))check(((ListView)a.findViewById(QiraatActivity.READINGS_LIST)).getCount()==10,"Ten reading groups");shot(a,name.replace('.','-')+"-"+(dark?"night":"day"));if(name.equals("QiblaActivity")||name.equals("PrayerActivity")){ui(()->{try{call(a,name.equals("QiblaActivity")?"settings":"calculationSettings");}catch(Exception e){throw new RuntimeException(e);}});shot(a,name+"-settings-"+(dark?"night":"day"));}ui(a::finish);log("Opened "+name+" "+(dark?"night":"day"));}}
 prefs.edit().putBoolean("nightMode",false).commit();check(getTargetContext().getPackageManager().getPackageInfo("app.layan.quran",0).versionName.equals("18.12"),"Version unchanged");}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_OK;try{String mode=args==null?"all":args.getString("mode","all");if(mode.equals("menus"))menus();else{if(!mode.equals("ui"))calculations();if(!mode.equals("calculations")){livePrayer();styles();themeToggle();}}result.putString("result","PASS "+checks+" assertions");}catch(Throwable e){code=Activity.RESULT_CANCELED;log(android.util.Log.getStackTraceString(e));result.putString("error",e.toString());}result.putString("report",report.toString());try{File f=new File(getTargetContext().getExternalFilesDir("tests"),"style-prayer-regression-"+(args==null?"all":args.getString("mode","all"))+".log");try(FileOutputStream out=new FileOutputStream(f)){out.write(report.toString().getBytes("UTF-8"));}}catch(Exception ignored){}finish(code,result);}
}
